<?php require __DIR__.'/config/db.php';require __DIR__.'/includes/auth.php';require_role(['office','admin']);$u=$_SESSION['user'];$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$status=$_POST['status']??'';$note=trim($_POST['note']??'');if(in_array($status,['Pending','Cleared','Rejected'],true)){if($u['role']==='admin'){$q=$pdo->prepare('UPDATE clearance_requests SET status=?,office_note=?,reviewed_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$q->execute([$status,$note,$u['id'],$id]);}else{$q=$pdo->prepare('UPDATE clearance_requests SET status=?,office_note=?,reviewed_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND office_id=?');$q->execute([$status,$note,$u['id'],$id,$u['office_id']]);}$notice='Status update godhame.';}}
$sql='SELECT cr.*,s.full_name,s.student_no,o.name office_name FROM clearance_requests cr JOIN students s ON s.id=cr.student_id JOIN offices o ON o.id=cr.office_id';$args=[];if($u['role']!=='admin'){$sql.=' WHERE cr.office_id=?';$args[]=$u['office_id'];}$sql.=' ORDER BY cr.updated_at DESC';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();$pageTitle='Office Requests';require __DIR__.'/includes/header.php';?>
<h1>Clearance requests</h1><?php if($notice):?><p class="success"><?=h($notice)?></p><?php endif;?><section class="panel"><div class="tablewrap"><table><tr><th>Student</th><th>Office</th><th>Student note</th><th>Update</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['full_name'])?><br><?=h($r['student_no'])?></td><td><?=h($r['office_name'])?><br><?=h($r['status'])?></td><td><?=h($r['student_note'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['Pending','Cleared','Rejected'] as $s):?><option <?=$s===$r['status']?'selected':''?>><?=$s?></option><?php endforeach;?></select><input name="note" placeholder="Office note" value="<?=h($r['office_note'])?>"><button>Save</button></form></td></tr><?php endforeach;?></table></div></section><?php require __DIR__.'/includes/footer.php';?>